import{_ as t,o as r,c as a,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Applications HA UGSo","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects-mqtt/index.md","filePath":"fr/projects-mqtt/index.md","lastUpdated":1793123188000}'),o={name:"fr/projects-mqtt/index.md"};function i(n,e,l,p,d,u){return r(),a("div",null,[...e[0]||(e[0]=[s('<p><a id="mqtt-projets"></a><a id="statut"></a></p><h1 id="ugso-ha-apps" tabindex="-1">Applications HA UGSo <a class="header-anchor" href="#ugso-ha-apps" aria-label="Permalink to &quot;Applications HA UGSo {#ugso-ha-apps}&quot;">​</a></h1><p>Ce dépôt commun constitue le point de publication central pour toutes les applications Home Assistant de UGSo Software : applications MQTT, Grafik Visual Studio, « Blocks for HA » et projets futurs. Chaque application dispose de son propre sous-répertoire, de sa propre version et de sa propre documentation. L&#39;URL du dépôt existant reste inchangée.</p><h2 id="ugso-ha-apps-und-weitere-projekte" tabindex="-1">Applications HA UGSo et autres projets <a class="header-anchor" href="#ugso-ha-apps-und-weitere-projekte" aria-label="Permalink to &quot;Applications HA UGSo et autres projets {#ugso-ha-apps-und-weitere-projekte}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Projet</th><th>Documentation</th></tr></thead><tbody><tr><td><a href="/fr/projects/dashboard-user-manager/">Gestion des utilisateurs du tableau de bord</a></td><td>0.1.4 : Utilisateurs présentés sous forme de colonnes avec cases à cocher, affectation groupée ou individuelle, interface disponible en DE/EN/FR et sauvegarde du tableau de bord avant l&#39;enregistrement.</td></tr><tr><td><a href="/fr/projects/callmebot/">CallMeBot WhatsApp</a></td><td>Application HA expérimentale 0.1.4 : Profils de destinataires, messages WhatsApp via MQTT, interface en DE/EN/FR et blocs Blockly dédiés.</td></tr><tr><td><a href="/fr/projects/callmebot-signal/">CallMeBot Signal</a></td><td>Application HA expérimentale 0.1.0 : Messages Signal, profils basés sur un numéro de téléphone ou un UUID, espace de nommage MQTT dédié et intégration Blockly avec sélection de profils (DE/EN/FR).</td></tr><tr><td><a href="/fr/projects/blocks-for-ha/">Blocks for HA</a></td><td>Application HA expérimentale 0.1.3 : Blocs visuels pour les automatisations natives, importation/exportation YAML et branches conditionnelles extensibles ; éditeur accessible via HA Ingress.</td></tr><tr><td><a href="/fr/projects/grafik-visual-studio/">Grafik Visual Studio</a></td><td>Éditeur graphique et moteur d&#39;exécution pour les visualisations dans Home Assistant.</td></tr></tbody></table><p>Ces projets se trouvent dans le même dépôt (repository) que les applications MQTT suivantes.</p><h2 id="gemeinsames-add-on-repository" tabindex="-1">Dépôt d&#39;add-ons commun <a class="header-anchor" href="#gemeinsames-add-on-repository" aria-label="Permalink to &quot;Dépôt d&#39;add-ons commun {#gemeinsames-add-on-repository}&quot;">​</a></h2><p>Les projets MQTT sont désormais principalement distribués via un dépôt d&#39;add-ons commun pour Home Assistant. Il suffit d&#39;ajouter une seule URL de dépôt dans Home Assistant ; les différents projets apparaîtront ensuite individuellement dans la boutique d&#39;add-ons (Add-on Store).</p><p>URL du dépôt pour Home Assistant :</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Modules complémentaires inclus :</p><ul><li><p>FRITZ!Box to MQTT</p></li><li><p>Heizöl to MQTT</p></li><li><p>Parcel to MQTT (développement arrêté)</p></li><li><p><a href="/fr/projects/mqtt-client/">Client MQTT</a> : permet de transmettre des appareils et des valeurs sélectionnés depuis Home Assistant vers ioBroker ou un broker MQTT externe. <strong>0.1.16</strong> ajoute la prise en charge des changements d&#39;état en temps réel (avec un mécanisme de secours par interrogation), des statuts détaillés, un nettoyage confirmé des anciens sujets « retain » (persistants), des commandes de contrôle supplémentaires, la sauvegarde des paramètres au format JSON et la gestion de certificats TLS personnalisés. Les paramètres existants restent valides ; les données « retain » ne sont pas supprimées automatiquement. Le broker HA déjà en place demeure inchangé.</p></li><li><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons" target="_blank" rel="noreferrer">Ouvrir le dépôt commun de modules complémentaires sur GitHub</a></p></li></ul><p>Les anciens dépôts individuels restent accessibles en tant qu&#39;archives historiques et renvoient vers ce dépôt commun.</p><h2 id="fritz-box-to-mqtt" tabindex="-1">FRITZ!Box to MQTT <a class="header-anchor" href="#fritz-box-to-mqtt" aria-label="Permalink to &quot;FRITZ!Box to MQTT {#fritz-box-to-mqtt}&quot;">​</a></h2><p><strong>FRITZ!Box to MQTT</strong></p><p>Une application pour Home Assistant qui expose les données de la FRITZ!Box sous forme d&#39;entités via la découverte MQTT (MQTT Discovery). Elle combine le protocole TR-064, des requêtes sur l&#39;interface web/Lua de la FRITZ!Box et la surveillance des appels en temps réel.</p><ul><li><a href="/fr/projects/fritzbox-to-mqtt/">Ouvrir la documentation de FRITZ!Box-to-MQTT</a></li><li><a href="https://github.com/rockbaer2007/fritzbox-to-mqtt" target="_blank" rel="noreferrer">Ouvrir le dépôt individuel archivé sur GitHub</a></li></ul><h2 id="heizol-to-mqtt" tabindex="-1">Heizöl to MQTT <a class="header-anchor" href="#heizol-to-mqtt" aria-label="Permalink to &quot;Heizöl to MQTT {#heizol-to-mqtt}&quot;">​</a></h2><p><strong>Heizöl to MQTT</strong></p><p>Une application pour Home Assistant qui met à disposition les prix du fioul domestique (provenant d&#39;Esyoil et Heizöl24) sous forme d&#39;entités via la découverte MQTT (MQTT Discovery). Actuellement, les meilleurs prix ainsi que jusqu&#39;à six offres de fournisseurs par source et par quantité sont publiés.</p><ul><li><a href="/fr/projects/heizoel-to-mqtt/">Ouvrir la documentation de Heizöl-to-MQTT</a></li><li><a href="https://github.com/rockbaer2007/heizoel-to-mqtt" target="_blank" rel="noreferrer">Ouvrir le dépôt archivé sur GitHub</a></li><li>Adapté de : <a href="https://github.com/TA2k/ioBroker.heizoel" target="_blank" rel="noreferrer">TA2k/ioBroker.heizoel</a></li></ul><h2 id="parcel-to-mqtt" tabindex="-1">Parcel to MQTT <a class="header-anchor" href="#parcel-to-mqtt" aria-label="Permalink to &quot;Parcel to MQTT {#parcel-to-mqtt}&quot;">​</a></h2><p><strong>Parcel to MQTT</strong></p><p><strong>Développement arrêté :</strong> Parcel Tracker est un projet bien plus abouti. Par conséquent, nous cessons le développement de notre propre solution. Nous vous invitons à découvrir <a href="https://github.com/SoerenKaiser99/parcel_tracker" target="_blank" rel="noreferrer">Parcel Tracker, par SoerenKaiser99</a>. La documentation existante est conservée à titre d&#39;archive.</p><p>Une application pour Home Assistant qui intègre le suivi de colis sous forme d&#39;entités via « MQTT Discovery ». La version actuelle prend en charge les listes de colis issues d&#39;un compte DHL, les numéros de suivi DHL (optionnels) ainsi que le suivi des colis Hermes.</p><ul><li><a href="/fr/projects/parcel-to-mqtt/">Ouvrir la documentation de Parcel-to-MQTT</a></li><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/parcel_to_mqtt" target="_blank" rel="noreferrer">Ouvrir le paquet dans le dépôt d&#39;add-ons partagé</a></li><li><a href="https://github.com/rockbaer2007/parcel-to-mqtt" target="_blank" rel="noreferrer">Ouvrir le dépôt archivé sur GitHub</a></li><li>Adapté de : <a href="https://github.com/TA2k/ioBroker.parcel" target="_blank" rel="noreferrer">TA2k/ioBroker.parcel</a></li></ul><h2 id="weitere-projektbereiche" tabindex="-1">Autres domaines de projet <a class="header-anchor" href="#weitere-projektbereiche" aria-label="Permalink to &quot;Autres domaines de projet {#weitere-projektbereiche}&quot;">​</a></h2><ul><li><a href="/fr/projects/">Ouvrir les projets C#</a></li><li><a href="/fr/projects-diverse/">Ouvrir divers projets</a></li><li><a href="/fr/projects/atlas/">Ouvrir ATLAS</a></li></ul>',28)])])}const h=t(o,[["render",i]]);export{m as __pageData,h as default};
